/**
 * troubleshootingRunbooks.ts — runbooks universales de troubleshooting L1/L2.
 * 42 guías paso a paso 100% offline (V6 FASE 4a). Migran el contenido de las
 * antiguas tools checklist HelpDesk (Password/MFA Reset, BitLocker, Outlook,
 * Printer, BSOD, File Share, Remote Assist, GPO) a formato runbook universal.
 */
export interface RunbookStep {
  /** Orden del paso (1..n). */
  order: number;
  /** Qué hacer (una acción clara). */
  action: string;
  /** Comando ejecutable de referencia (PowerShell/CMD) — opcional. */
  command?: string;
  /** Resultado esperado al ejecutarlo — opcional. */
  expected?: string;
}

export interface TroubleshootingRunbook {
  /** ID estable tipo RB-XX-NNN. */
  id: string;
  /** Título corto y accionable. */
  title: string;
  /** Categoría del runbook. */
  category: 'Cuenta e Identidad' | 'Windows / OS' | 'Redes' | 'Microsoft 365' | 'Hardware y Periféricos' | 'Service Desk';
  /** Síntomas típicos que reporta el usuario (2-4). */
  symptoms: string[];
  /** Verificaciones rápidas antes de la escalera larga (2-4). */
  quick_wins: string[];
  /** Pasos ordenados (5-9 pasos, con comandos reales cuando aplique). */
  steps: RunbookStep[];
  /** Cómo verificar que el problema quedó resuelto. */
  verification: string;
  /** Cuándo y a quién escalar (L2/L3/administración). */
  escalation: string;
  /** Dataset universal — siempre true. */
  is_universal: true;
  /** Tags ES/EN para búsqueda fuzzy (incluir sinónimos). */
  tags: string[];
}

