    symptoms: ['El mapeo de unidades o el fondo corporativo no aparece en mi equipo', 'Los settings del dominio no llegan a este equipo y al resto sí', 'Ayer aplicaba y hoy no tras un cambio en las directivas'],
    quick_wins: [
      'Comparar con otro equipo de la MISMA OU: si el otro sí aplica, es el equipo (herencia, filtrado, salud del cliente GPO)',
      'Preguntar si el equipo estuvo fuera de la red corporativa (VPN remota: las GPO tardan o se marcan slow-link)',
      'Reiniciar y reintentar: el cliente de GPO se recupera de estados atascados',
    ],
    steps: [
      { order: 1, action: 'Forzar el procesado y ver si el cliente GPO funciona', command: 'gpupdate /force', expected: '"Computer Policy update has completed successfully" — si falla aquí, el problema es del cliente (red/servicio), no del alcance' },
      { order: 2, action: 'Ver qué GPOs se aplicaron Y cuáles fueron rechazadas con su motivo', command: 'gpresult /r', expected: 'Secciones "Applied Group Policy Objects" y "Denied Group Policy Objects" (filtro de seguridad, vacía, WMI)' },
      { order: 3, action: 'Generar el reporte completo HTML con el usuario concreto', command: 'gpresult /h C:\\temp\\gpo.html /f /user EMPRESA\\usuario', expected: 'Reporte con cada GPO, su estado y los settings aplicados — el documento de diagnóstico' },
      { order: 4, action: 'Verificar el LSDOU (orden de procesado: Local → Site → Domain → OU, la última gana) y la herencia en GPMC', expected: 'El equipo está en la OU esperada, sin "Block Inheritance" y sin otra GPO "Enforced" pisando la del ticket' },
      { order: 5, action: 'Verificar el security filtering: la GPO aplica solo a lo listado en Scope → Security Filtering', expected: 'El EQUIPO (para Computer Configuration) o el usuario está en el grupo del filtro — "Authenticated Users" quitado es la causa clásica' },
      { order: 6, action: 'Probar el WMI filter de la GPO contra el equipo', command: 'Get-WmiObject -Namespace root\\CIMv2 -Query "SELECT * FROM Win32_OperatingSystem" | Select Caption', expected: 'La query del filtro devuelve resultado en el equipo = no lo excluye; error o vacío = el WMI filter lo filtra fuera' },
      { order: 7, action: 'Revisar la salud del cliente GPO en el log operativo', command: 'Get-WinEvent -LogName "Microsoft-Windows-GroupPolicy/Operational" -MaxEvents 20', expected: 'Ciclos de procesado sin errores; fallos de red hacia el DC o eventos de error apuntan a la causa' },
      { order: 8, action: 'Última instancia: reconstruir la política local (se regenera al procesar)', command: 'Ren C:\\Windows\\System32\\GroupPolicy\\Machine\\Registry.pol Registry.pol.bak ; gpupdate /force', expected: 'Registry.pol se regenera y las directivas de dominio vuelven a escribir el registry' },
    ],
    verification: 'gpresult /r muestra la GPO en "Applied Group Policy Objects" y el setting concreto es visible en el equipo (verificado con el usuario).',
    escalation: 'Si la GPO no aplica a NINGÚN equipo de la OU tras gpupdate /force, o gpresult la marca "Denied (Empty)", o hay errores de replicación SYSVOL (DFSR): escalar a administración de sistemas/AD — problema de infraestructura de directivas.',
    is_universal: true,
    tags: ['gpo', 'group policy', 'gpupdate', 'gpresult', 'lsdou', 'security filtering', 'wmi filter', 'block inheritance', 'enforced', 'directiva', 'sysvol', 'windows'],
